-- PT105-S1-Q12. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT105-S1-Q12$batch05$ AND q.stimulus=$batch05$Alice will volunteer to work on the hospital fundraising drive only if her brother Bruce also volunteers and a majority of the others working on the drive promise to select Bruce to manage the drive. However, although Bruce is willing to volunteer, none of the others working on the drive will promise to select Bruce to manage the drive. Thus it is certain that Alice will not volunteer.$batch05$ AND q.prompt=$batch05$In which one of the following arguments is the pattern of reasoning most similar to the pattern of reasoning in the argument above?$batch05$ AND q.correct_choice=$batch05$C$batch05$) THEN RAISE EXCEPTION 'Question changed: PT105-S1-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT105-S1-Q12$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S1-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT105-S1-Q12$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Alice will certainly not volunteer.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Alice volunteers only if two things both happen: Bruce volunteers, and the others promise to make Bruce manager. Bruce will volunteer, but the others will not promise.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Strip it to a skeleton. A happens only if B *and* C. B happens. C does not. So A certainly does not. One missing requirement is enough to rule A out. Look for an argument with two requirements, one met and one failed, and a certain "no."$batch05$), (3, $batch05$Goal$batch05$, $batch05$A only if B and C. B yes, C no. Certainly not A.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT105-S1-Q12$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Only one requirement, and the conclusion is "likely," not certain.$batch05$), ($batch05$B$batch05$, $batch05$The most popular wrong answer, because it has "only if" and a certain conclusion. But it reverses the rule. Leon goes only if Vera goes, yet the argument concludes something about Vera from Leon. And it rests on a report from friends, not a fact.$batch05$), ($batch05$C$batch05$, $batch05$Jim goes only if Sam and Elaine both go. Sam goes, Elaine does not. So Jim certainly does not. A perfect skeleton match.$batch05$), ($batch05$D$batch05$, $batch05$A different structure entirely, with "if" rules about who works with whom.$batch05$), ($batch05$E$batch05$, $batch05$This one looks the closest: two requirements, one of them met, and a certain conclusion. But it concludes that Therese *will* work if the other requirement is met. That treats "only if" as "if." The original concludes a certain "no" from a requirement failing.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT105-S1-Q12$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
